import csv
import io

def total_cents(text):
    total = 0
    for row in csv.DictReader(io.StringIO(text)):
        amount = int(row["amount"])
        if amount <= 0:
            raise ValueError("金额必须大于 0")
        total = total + amount
    return total

assert total_cents("amount\n125\n75\n") == 200
print("合计检查通过")
try:
    total_cents("amount\n三\n")
except ValueError:
    print("金额格式错误")

